import{_ as a,o as r,c as o,a3 as t}from"./chunks/framework.DhF4LrUq.js";const m=JSON.parse('{"title":"Roles","description":"The nine ShipperDog personas - from platform operator to tester - each with a dedicated quickstart and a hand-off task list.","frontmatter":{"description":"The nine ShipperDog personas - from platform operator to tester - each with a dedicated quickstart and a hand-off task list."},"headers":[],"relativePath":"roles/index.md","filePath":"roles/index.md"}'),n={name:"roles/index.md"};function s(i,e,d,l,p,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h1><p>ShipperDog&#39;s role catalog maps to nine documentation personas. Each persona gets a dedicated quickstart — who you are, what you can do, your first fifteen minutes in the real product, and where to go next — ending in a hand-off task list. Hold more than one role? Work one track per session and pick the persona you are being right now. Hit a wall anywhere? <a href="/shipperdog/snapshot/reference/troubleshooting">Troubleshooting</a> lists the top ten scenarios across all nine tracks.</p><h2 id="platform-operator" tabindex="-1"><a href="/shipperdog/snapshot/roles/platform-operator">Platform Operator</a> <a class="header-anchor" href="#platform-operator" aria-label="Permalink to &quot;[Platform Operator](/roles/platform-operator.md)&quot;">​</a></h2><p><code>platform_admin</code> — Console and Terraform. Org onboarding, instance health, cross-tenant operations, break-glass.</p><h2 id="organization-administrator" tabindex="-1"><a href="/shipperdog/snapshot/roles/org-admin">Organization Administrator</a> <a class="header-anchor" href="#organization-administrator" aria-label="Permalink to &quot;[Organization Administrator](/roles/org-admin.md)&quot;">​</a></h2><p><code>ORG_ADMIN</code> — Console. Members and roles, tenants, IdP/SCIM/SSO configuration, channel credentials, ABAC and SIEM policies.</p><h2 id="release-manager" tabindex="-1"><a href="/shipperdog/snapshot/roles/release-manager">Release Manager</a> <a class="header-anchor" href="#release-manager" aria-label="Permalink to &quot;[Release Manager](/roles/release-manager.md)&quot;">​</a></h2><p><code>RELEASE_MANAGER</code> — Console and CLI. Release creation through approvals, gates, ring promotion, staged rollout, and rollback.</p><h2 id="app-owner-product" tabindex="-1"><a href="/shipperdog/snapshot/roles/app-owner">App Owner / Product</a> <a class="header-anchor" href="#app-owner-product" aria-label="Permalink to &quot;[App Owner / Product](/roles/app-owner.md)&quot;">​</a></h2><p><code>APP_OWNER</code> — Console. App registry, ownership scope, product approvals, release manifests, dashboards.</p><h2 id="developer" tabindex="-1"><a href="/shipperdog/snapshot/roles/developer">Developer</a> <a class="header-anchor" href="#developer" aria-label="Permalink to &quot;[Developer](/roles/developer.md)&quot;">​</a></h2><p><code>DEVELOPER</code> — CLI, CI, and Console. Artifact upload with provenance, versions and tags, CI actions (GitHub Actions, Jenkins, GitLab), gate feedback.</p><h2 id="qa-engineer" tabindex="-1"><a href="/shipperdog/snapshot/roles/qa-engineer">QA Engineer</a> <a class="header-anchor" href="#qa-engineer" aria-label="Permalink to &quot;[QA Engineer](/roles/qa-engineer.md)&quot;">​</a></h2><p><code>QA_ENGINEER</code> — Console and Portal admin views. Tester groups, feedback triage, crash-free gates, device fleet.</p><h2 id="security-compliance-reviewer" tabindex="-1"><a href="/shipperdog/snapshot/roles/security-reviewer">Security / Compliance Reviewer</a> <a class="header-anchor" href="#security-compliance-reviewer" aria-label="Permalink to &quot;[Security / Compliance Reviewer](/roles/security-reviewer.md)&quot;">​</a></h2><p><code>SECURITY_REVIEWER</code>, <code>COMPLIANCE_REVIEWER</code> — Console. Security feedback, approval signatures, audit trail, SIEM streams.</p><h2 id="tenant-admin" tabindex="-1"><a href="/shipperdog/snapshot/roles/tenant-admin">Tenant Admin</a> <a class="header-anchor" href="#tenant-admin" aria-label="Permalink to &quot;[Tenant Admin](/roles/tenant-admin.md)&quot;">​</a></h2><p><code>TENANT_ADMIN</code> — Console, tenant-scoped. Tenant members, devices, tenant dashboard, app visibility.</p><h2 id="tester" tabindex="-1"><a href="/shipperdog/snapshot/roles/tester">Tester</a> <a class="header-anchor" href="#tester" aria-label="Permalink to &quot;[Tester](/roles/tester.md)&quot;">​</a></h2><p><code>TENANT_TESTER</code> — Tester Portal and the companion app. Accept an invite, browse apps, install builds, submit feedback. The one persona with zero Console access — the Portal track is fully standalone: invite email to first install in under five minutes.</p>',20)])])}const f=a(n,[["render",s]]);export{m as __pageData,f as default};
